import type { TeachingPeriod } from "./types"
import periodsJson from "@/data/teaching-periods.json"

/**
 * Teaching period IDs are arbitrary QUT Virtual 4 content IDs and they rotate
 * every year. They used to be hand-edited in this file each semester, which is
 * why the list still advertised delisted 2025/2026 periods that return errors.
 *
 * `data/teaching-periods.json` is now generated by `scripts/discover-periods.js`,
 * which reads the IDs QUT actually publishes on its unit search pages. Refresh it
 * with `npm run periods:refresh` (and a scheduled CI job does the same monthly).
 */

interface DiscoveredPeriod {
  id: string
  code: string
  name: string
  campus: string
  dateRange: string
  year: number
  semester: number
  seenOnUnits: number
}

const discovered: DiscoveredPeriod[] = (periodsJson.periods ?? []) as DiscoveredPeriod[]

/**
 * Some periods surface on only one probe unit. Those are single-school variants
 * that duplicate a mainstream semester, so they would only clutter the dropdown.
 * They stay in the valid-ID set below, just not in the picker.
 */
const MAINSTREAM_MIN_UNIT_COVERAGE = 2

function dedupeByPeriodCode(list: DiscoveredPeriod[]): DiscoveredPeriod[] {
  const best = new Map<string, DiscoveredPeriod>()
  for (const period of list) {
    const existing = best.get(period.code)
    if (!existing || period.seenOnUnits > existing.seenOnUnits) {
      best.set(period.code, period)
    }
  }
  return [...best.values()]
}

function toTeachingPeriod(period: DiscoveredPeriod): TeachingPeriod {
  return {
    id: period.id,
    name: period.name,
    campus: period.campus,
    dateRange: period.dateRange,
  }
}

function semesterOfDate(date: Date): { year: number; semester: 1 | 2 } {
  const month = date.getMonth() // 0-indexed
  const year = date.getFullYear()
  // Semester 1 runs Feb-Jun, Semester 2 runs Jul-Nov. Dec/Jan roll forward to
  // the coming Semester 1, which is the one students are enrolling in.
  if (month >= 6) return { year, semester: 2 }
  if (month >= 1) return { year, semester: 1 }
  return { year: year + 1, semester: 1 }
}

/**
 * Sorts so the period a student is most likely to want comes first: the current
 * semester, then upcoming ones, then past ones most-recent-first.
 */
function sortForPicker(list: DiscoveredPeriod[], now = new Date()): DiscoveredPeriod[] {
  const current = semesterOfDate(now)
  const rank = (p: DiscoveredPeriod) => {
    const isCurrent = p.year === current.year && p.semester === current.semester
    const isFuture = p.year > current.year || (p.year === current.year && p.semester > current.semester)
    return isCurrent ? 0 : isFuture ? 1 : 2
  }
  return [...list].sort((a, b) => {
    const rankDelta = rank(a) - rank(b)
    if (rankDelta !== 0) return rankDelta
    if (rank(a) === 2) {
      // Past periods: newest first.
      return b.year - a.year || b.semester - a.semester
    }
    return a.year - b.year || a.semester - b.semester
  })
}

/**
 * Only plain semester periods are offered in the picker. Exchange periods
 * (XCH-*) exist upstream but duplicate the same semester with an
 * exchange-specific class list, so choosing one instead of the plain semester
 * silently hides most classes. `discover-periods.js` already drops them; this
 * filter keeps a stale JSON file from reintroducing them.
 */
const SEMESTER_ONLY = /^SEM-/i

const mainstream = dedupeByPeriodCode(
  discovered.filter(
    (period) => period.seenOnUnits >= MAINSTREAM_MIN_UNIT_COVERAGE && SEMESTER_ONLY.test(period.code),
  ),
)

export const teachingPeriods: TeachingPeriod[] = sortForPicker(mainstream).map(toTeachingPeriod)

/**
 * Every ID QUT is currently advertising, including the single-school variants
 * filtered out of the picker. Anything in here is safe to send to QUT Virtual 4.
 */
const VIRTUAL4_TEACHING_PERIOD_IDS = new Set(discovered.map((period) => period.id))

// Retained for the handful of pre-2026 period IDs that still route to the
// legacy mytimetable endpoint rather than QUT Virtual 4.
const LEGACY_NEW_API_PERIOD_IDS = new Set(["621052"])

export function getTeachingPeriodById(id: string): TeachingPeriod | undefined {
  return teachingPeriods.find((period) => period.id === id)
}

export function getCurrentTeachingPeriod(): TeachingPeriod {
  const current = semesterOfDate(new Date())
  const match = mainstream.find(
    (period) => period.year === current.year && period.semester === current.semester,
  )
  if (match) return toTeachingPeriod(match)
  return teachingPeriods[0] ?? { id: "4381474", name: "Semester 2, 2026" }
}

export function formatTeachingPeriod(period: TeachingPeriod): string {
  return `${period.name} (${period.dateRange})`
}

export function getTeachingPeriodName(id: string): string {
  const period = teachingPeriods.find((p) => p.id === id)
  return period ? period.name : id
}

export function getTeachingPeriodId(name: string, campus?: string): string | undefined {
  if (campus) {
    const period = teachingPeriods.find((p) => p.name === name && p.campus === campus)
    return period?.id
  } else {
    const period = teachingPeriods.find((p) => p.name === name)
    return period?.id
  }
}

export function getTeachingPeriodWithCampus(id: string): string {
  const period = teachingPeriods.find((p) => p.id === id)
  if (!period) return id
  return period.campus ? `${period.name} @ ${period.campus}` : period.name
}

// QUT Virtual 4 SolrQuest endpoint (guest session + CSRF token)
export function shouldUseVirtual4API(teachingPeriodId: string): boolean {
  return VIRTUAL4_TEACHING_PERIOD_IDS.has(teachingPeriodId)
}

// Legacy mytimetable.qut.edu.au API (currently authenticated / unavailable)
export function shouldUseNewAPI(teachingPeriodId: string): boolean {
  return LEGACY_NEW_API_PERIOD_IDS.has(teachingPeriodId)
}

/** Exposed so tests can assert the discovery file stays in sync with the picker. */
export function getAllDiscoveredPeriods(): DiscoveredPeriod[] {
  return discovered
}
